from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
CONFIG={'mode': 'sec', 'report': 'events.json', 'title': 'SEC disclosure explorer', 'subtitle': 'Connect corporate disclosures with observable market reactions. Explore a bounded sample of public filings and historical adjusted prices.', 'story': '<h3>01 · Connect the evidence</h3><p>Join company identifiers, SEC filing metadata and daily prices. Keep source links so every event can be inspected.</p><h3>02 · Align the event window</h3><p>Map filings to trading sessions and normalize prices to the previous session. Inspect the path, not just a single return.</p><h3>03 · Investigate, then test</h3><p>Use the explorer to generate hypotheses. A causal event study requires a benchmark, timing controls and confounder checks.</p>', 'limit': 'Raw price reactions are not abnormal returns or evidence that a filing caused a move. The sample is historical and deliberately bounded.', 'footer': 'Public filing metadata + historical price-derived returns. No full filing text or database credentials.'}
TEMPLATE='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__</title><style>\n:root{--navy:#132b3c;--teal:#117f82;--paper:#f3f5f3;--muted:#526675;--line:#dae2e3}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--navy);font:16px/1.6 system-ui,sans-serif}header{background:var(--navy);color:white;padding:44px max(6vw,20px) 48px}header .eyebrow{color:#7fdad0;font-size:12px;letter-spacing:3px;text-transform:uppercase}h1{font-size:clamp(28px,4vw,48px);line-height:1.15;max-width:900px;margin:16px 0}header p{max-width:850px;color:#c6d9e0}header a{color:#9fe8de;margin-right:24px}main{max-width:1180px;margin:30px auto;padding:0 20px 50px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.card,.panel{background:white;border:1px solid var(--line);border-radius:12px;padding:24px}.card b{display:block;font-size:30px;line-height:1.2}.card span{color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:1.6fr 1fr;gap:20px}.panel{margin-bottom:20px}h2{font-size:21px;margin:0 0 14px}h3{font-size:16px}p{margin:10px 0}label{font-size:13px;color:var(--muted);display:inline-block;margin:0 16px 14px 0}select{display:block;max-width:100%;padding:9px 12px;margin-top:5px;border:1px solid #b9cbd0;border-radius:6px;background:white;color:var(--navy);font:inherit}button:focus,a:focus,select:focus{outline:3px solid #f6bd59;outline-offset:3px}.barrow{display:grid;grid-template-columns:minmax(110px,180px) 1fr 75px;gap:12px;align-items:center;font-size:13px;margin:15px 0}.track{height:16px;background:#edf2f2;border-radius:3px;overflow:hidden}.fill{height:100%;background:var(--teal)}.small{font-size:13px;color:var(--muted)}.note{padding:15px 18px;border-left:3px solid var(--teal);background:#eaf4f2;font-size:14px}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--muted)}svg{width:100%;height:auto}.legend{font-size:13px;color:var(--muted)}footer{font-size:12px;color:var(--muted);padding-top:15px;border-top:1px solid var(--line)}@media(max-width:760px){.grid{grid-template-columns:1fr}.cards{grid-template-columns:1fr}.barrow{grid-template-columns:110px 1fr 60px}header{padding-top:30px}select{width:100%}}\n</style></head><body><header><div class="eyebrow">Applied analytics · Project evidence</div><h1>__TITLE__</h1><p>__SUBTITLE__</p><a href="https://github.com/yc4704/__REPO__">Code & methodology ↗</a><a href="../reports/__REPORT__" download>Download results JSON</a></header><main><div id="cards" class="cards"></div><div class="grid"><section class="panel"><h2 id="charttitle"></h2><div id="controls"></div><div id="chart" aria-live="polite"></div><p id="chartnote" class="small"></p></section><aside class="panel"><h2>From question to decision</h2>__STORY__<div class="note">__LIMIT__</div></aside></div><section class="panel"><h2>Evidence table</h2><div class="tablewrap" id="table"></div></section><footer>Coursework portfolio · Curated October 2026 · __FOOTER__</footer></main><script>\nconst D=__DATA__, MODE=\'__MODE__\';\nconst el=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nfunction cards(v){el(\'cards\').innerHTML=v.map(([n,l])=>`<div class="card"><b>${esc(n)}</b><span>${esc(l)}</span></div>`).join(\'\')}\nfunction table(headers,rows){el(\'table\').innerHTML=\'<table><thead><tr>\'+headers.map(h=>\'<th>\'+esc(h)+\'</th>\').join(\'\')+\'</tr></thead><tbody>\'+rows.map(r=>\'<tr>\'+r.map(c=>\'<td>\'+esc(c)+\'</td>\').join(\'\')+\'</tr>\').join(\'\')+\'</tbody></table>\'}\nfunction bars(rows,maxv){el(\'chart\').innerHTML=rows.map(r=>`<div class="barrow"><span>${esc(r[0])}</span><div class="track"><div class="fill" style="width:${Math.max(0,Math.min(100,r[1]/maxv*100))}%"></div></div><strong>${esc(r[2])}</strong></div>`).join(\'\')}\nfunction select(id,label,values){const l=document.createElement(\'label\');l.textContent=label;const s=document.createElement(\'select\');s.id=id;for(const [v,t]of values){const o=document.createElement(\'option\');o.value=v;o.textContent=t;s.append(o)}l.append(s);el(\'controls\').append(l);return s}\nif(MODE===\'attrition\'){\nconst dept=select(\'department\',\'Department\',[[\'All\',\'All departments\'],...D.departments.map(d=>[d.department,d.department])]);\nconst overtime=select(\'overtime\',\'Overtime\',[[\'All\',\'All\'],[\'Yes\',\'Yes\'],[\'No\',\'No\']]);\nconst update=()=>{const gs=D.groups.filter(g=>(dept.value===\'All\'||g.department===dept.value)&&(overtime.value===\'All\'||g.overtime===overtime.value));const n=gs.reduce((s,g)=>s+g.n,0),k=gs.reduce((s,g)=>s+g.left,0);cards([[n,\'Simulated employees in selection\'],[k,\'Observed attrition cases\'],[n?(k/n*100).toFixed(1)+\'%\':\'—\',\'Observed attrition rate\']]);\nconst rows=[...new Set(gs.map(g=>g.work_life_balance))].sort().map(v=>{const sub=gs.filter(g=>g.work_life_balance===v),n=sub.reduce((s,g)=>s+g.n,0),k=sub.reduce((s,g)=>s+g.left,0);return {v,n,k,rate:k/n*100}});\nel(\'charttitle\').textContent=\'Attrition by work–life balance\';bars(rows.map(r=>[\'Rating \'+r.v,r.rate,r.rate.toFixed(1)+\'%\']),100);el(\'chartnote\').textContent=\'Observed rates, not individual predictions. Check sample sizes below; small cells are unstable. Ratings retain the original dataset coding.\';table([\'Work–life rating\',\'Employees\',\'Attrition cases\',\'Rate\'],rows.map(r=>[r.v,r.n,r.k,r.rate.toFixed(1)+\'%\']));};dept.onchange=overtime.onchange=update;update();\n}else if(MODE===\'spend\'){\ncards([[D.train_rows.toLocaleString(),\'Training rows\'],[D.test_rows.toLocaleString(),\'Untouched holdout rows\'],[\'Top 10%\',\'Original course competition · owner-reported\']]);\nconst metric=select(\'metric\',\'Validation metric\',[[\'rmse\',\'RMSE · lower is better\'],[\'mae\',\'MAE · lower is better\'],[\'r2\',\'R² · higher is better\'],[\'mape_percent\',\'MAPE (%) · lower is better\']]);\nconst update=()=>{el(\'charttitle\').textContent=\'Independent holdout benchmark\';const max=Math.max(...D.metrics.map(m=>m[metric.value]),.001);bars(D.metrics.map(m=>[m.model,m[metric.value],m[metric.value].toFixed(3)]),metric.value===\'r2\'?1:max*1.05);el(\'chartnote\').textContent=D.protocol;table([\'Model\',\'R²\',\'RMSE\',\'MAE\',\'MAPE %\'],D.metrics.map(m=>[m.model,m.r2.toFixed(4),m.rmse.toFixed(2),m.mae.toFixed(2),m.mape_percent.toFixed(2)]));};metric.onchange=update;update();\n}else if(MODE===\'deepseek\'){\ncards([[\'12\',\'Model / feature-set comparisons\'],[\'154–158\',\'Labeled observations · varies by feature set\'],[\'20% / 20%\',\'Bottom / top CAR quantiles\']]);\nconst metric=select(\'metric\',\'Metric\',[[\'roc_auc_mean\',\'ROC-AUC\'],[\'accuracy_mean\',\'Accuracy\'],[\'f1_mean\',\'F1\']]);const set=select(\'features\',\'Feature set\',[[\'All\',\'All feature sets\'],...Array.from(new Set(D.metrics.map(x=>x.feature_set))).map(x=>[x,x])]);\nconst update=()=>{const rs=D.metrics.filter(r=>set.value===\'All\'||r.feature_set===set.value);el(\'charttitle\').textContent=\'Does text add predictive signal?\';bars(rs.map(r=>[r.feature_set.replace(\'X_fin_plus_X_text\',\'Combined\').replace(\'X_fin_only\',\'Finance\').replace(\'X_text_only\',\'Text\')+\' / \'+r.model_name,r[metric.value],r[metric.value].toFixed(3)]),1);el(\'chartnote\').textContent=\'Archived 5-fold CV means. Fold standard deviations are shown below; they are not confidence intervals. Upstream feature fitting has not been independently audited.\';table([\'Features\',\'Model\',\'n\',\'Metric mean\',\'Fold SD\'],rs.map(r=>[r.feature_set,r.model_name,r.n_samples,r[metric.value].toFixed(4),r[metric.value.replace(\'_mean\',\'_std\')].toFixed(4)]));};metric.onchange=set.onchange=update;update();\n}else if(MODE===\'sec\'){\nconst tickers=Array.from(new Set(D.events.map(e=>e.ticker))).sort();const ticker=select(\'ticker\',\'Company\',tickers.map(t=>[t,t]));const event=select(\'event\',\'Filing\',[]);\nfunction populate(){event.innerHTML=\'\';D.events.forEach((e,i)=>{if(e.ticker===ticker.value){let o=document.createElement(\'option\');o.value=i;o.textContent=e.filing_date+\' · \'+e.form;event.append(o)}});update()}\nfunction update(){const e=D.events[Number(event.value)];if(!e)return;cards([[D.events.length,\'Historical filings in bounded sample\'],[D.companies,\'Companies represented\'],[e.form,e.ticker+\' · \'+e.filing_date]]);el(\'charttitle\').textContent=e.company;const points=e.window;let lo=Math.min(0,...points.map(p=>p.return_pct)),hi=Math.max(0,...points.map(p=>p.return_pct));const pad=Math.max((hi-lo)*.15,.1);lo-=pad;hi+=pad;const left=60,right=620,top=20,bottom=260;const minday=Math.min(...points.map(p=>p.day)),maxday=Math.max(...points.map(p=>p.day));const x=d=>left+(d-minday)/(maxday-minday||1)*(right-left),y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);let svg=`<svg viewBox="0 0 650 320" role="img" aria-label="Adjusted-close price reaction around selected filing">`;for(let i=0;i<5;i++){let v=lo+(hi-lo)*i/4;svg+=`<line x1="${left}" x2="${right}" y1="${y(v)}" y2="${y(v)}" stroke="#dae2e3"/><text x="4" y="${y(v)+4}" font-size="11" fill="#526675">${v.toFixed(1)}%</text>`}svg+=`<line x1="${x(0)}" x2="${x(0)}" y1="20" y2="260" stroke="#d88e38" stroke-dasharray="5 4"/><polyline points="${points.map(p=>x(p.day)+\',\'+y(p.return_pct)).join(\' \')}" fill="none" stroke="#117f82" stroke-width="3"/>`;for(const d of [minday,0,maxday])svg+=`<text x="${x(d)}" y="284" text-anchor="middle" font-size="12">${d}</text>`;svg+=\'<text x="300" y="310" text-anchor="middle" font-size="12">Trading days relative to filing (day 0)</text></svg>\';el(\'chart\').innerHTML=svg;\nel(\'chartnote\').textContent=D.method;const link=document.createElement(\'a\');link.textContent=\'Open source filing at SEC ↗\';try{const u=new URL(e.url);if(u.hostname===\'www.sec.gov\'){link.href=u.href;link.target=\'_blank\';link.rel=\'noopener\';el(\'chartnote\').append(document.createElement(\'br\'),link)}}catch{}table([\'Relative trading day\',\'Date\',\'Cumulative price return\'],points.map(p=>[p.day,p.date,p.return_pct.toFixed(3)+\'%\']));}ticker.onchange=populate;event.onchange=update;populate();}\n</script></body></html>'
REPO='sec-disclosure-explorer'
report=json.loads((ROOT/'reports'/CONFIG['report']).read_text(encoding='utf-8'))
page=TEMPLATE
for key,value in {**CONFIG,'repo':REPO,'data':json.dumps(report,ensure_ascii=False).replace('<','\\u003c')}.items():page=page.replace('__'+key.upper()+'__',value)
page=page.replace('../reports/'+CONFIG['report'],'results.json')
(ROOT/'docs').mkdir(exist_ok=True)
(ROOT/'docs/index.html').write_text(page,encoding='utf-8')
(ROOT/'docs/results.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
